// Copies the worktree to a temp dir so a run is not disturbed by edits made while it runs.
import { mkdtempSync, symlinkSync, existsSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { run } from "./util.mjs";

const EXCLUDES = [
  "node_modules", ".next", ".open-next", ".wrangler", ".git", ".worktree",
  "quality",                    // evidence from earlier runs
  "tools/quality",              // the checker itself is not part of the site
  "src/content/guides.generated.ts", "public/guides",   // regenerated by the build
  ".DS_Store",
];

export async function freeze(repoRoot) {
  const dir = mkdtempSync(join(tmpdir(), "dt-quality-"));
  const args = ["-a", ...EXCLUDES.flatMap((e) => ["--exclude", e]), `${repoRoot}/`, `${dir}/`];
  const r = await run("rsync", args, { cwd: repoRoot });
  if (r.code !== 0) throw new Error(`rsync failed: ${r.out}`);
  // node_modules: Turbopack refuses a symlink that points outside the project root ("Could not find the Next.js
  // package"), so the default is an APFS clone (copy-on-write, near-instant, no extra disk). QUALITY_NODE_MODULES_MODE=symlink
  // keeps the old behaviour for bundlers that accept it.
  if ((process.env.QUALITY_NODE_MODULES_MODE ?? "clone") === "symlink") linkModules(repoRoot, dir, "symlink");
  else await cloneModules(repoRoot, dir);
  return dir;
}

export function linkModules(repoRoot, dir, mode) {
  const target = join(repoRoot, "node_modules");
  const link = join(dir, "node_modules");
  if (existsSync(link)) return;
  if (mode === "symlink") symlinkSync(target, link, "dir");
  else mkdirSync(link);
}

export async function cloneModules(repoRoot, dir) {
  const link = join(dir, "node_modules");
  await run("rm", ["-rf", link]);
  const r = await run("cp", ["-Rc", join(repoRoot, "node_modules"), link]);
  if (r.code !== 0) throw new Error(`cp -Rc node_modules failed: ${r.out}`);
}
